"use strict";
const DEST_CHECKS=[
{id:'access',title:P('Page khulti hai?','Can the page be reached?'),test:P('Final aur mobile URL, redirects, common browsers, target location aur AdsBot access test karo. HTTP error ki details likho.','Test final/mobile URLs, redirects, common browsers, target location and AdsBot access. Record any HTTP errors.'),urgent:true},
{id:'promise',title:P('Ad ka wada milta hai?','Is the ad promise delivered?'),test:P('Search → ad → page compare karo. Product/service, price aur offer ki conditions visible hain?','Compare search → ad → page. Are the product/service, price and offer conditions visible?'),urgent:false},
{id:'action',title:P('Kaam complete hota hai?','Can the action be completed?'),test:P('Mobile par valid aur invalid form, checkout/call link aur confirmation test karo. Test order ko fulfill mat karo.','Test valid/invalid mobile forms, checkout/call links and confirmation. Do not fulfill test orders.'),urgent:true},
{id:'mobile',title:P('Chhoti screen par asaan?','Usable on a small screen?'),test:P('Real phone/network par load aur interaction dekho. Blocked button, overflow aur obstructing pop-up ki evidence lo.','Inspect loading and interaction on a real phone/network. Record blocked buttons, overflow or obstructing pop-ups.'),urgent:false},
{id:'terms',title:P('Decision ki information clear?','Is decision information clear?'),test:P('Business identity/contact, total charges, coverage, delivery/returns ya service terms ko offer ke mutabiq check karo.','Check business identity/contact, total charges, coverage, delivery/returns or service terms for this offer.'),urgent:false},
{id:'measure',title:P('Asal outcome measure hota hai?','Is the actual outcome measured?'),test:P('Success ko backend/CRM se reconcile karo. Invalid submit, duplicate aur consent states separately test karo.','Reconcile success with backend/CRM records. Test invalid submissions, duplicates and consent states separately.'),urgent:true},
{id:'privacy',title:P('Data ka istemal samajh aata hai?','Is data use explained?'),test:P('Sirf zaroori fields lo; privacy notice aur applicable consent/data requirements ka responsible review record karo. Ye legal audit nahi.','Request necessary fields; record responsible review of privacy notice and applicable consent/data requirements. This is not a legal audit.'),urgent:false},
{id:'handoff',title:P('Enquiry ke baad kya hota hai?','What happens after the enquiry?'),test:P('Confirmation, response owner/time, stock/capacity aur follow-up ka test record likho.','Record confirmation, response owner/time, stock/capacity and a follow-up test.'),urgent:false}
];
const DEST_FIELDS=['query','promise','url','headline','cta','owner','next','evidence'];
let destinationTab='cases',destinationCase=0;
function cleanDestination(v){const out={};if(!v||typeof v!=='object')return out;for(const b of BUSINESSES){const x=v[b.id];if(!x||typeof x!=='object')continue;const r={answers:{},checks:{},plan:{},model:{}};for(let i=0;i<6;i++)if(Number.isInteger(x.answers?.[i])&&x.answers[i]>=0&&x.answers[i]<3)r.answers[i]=x.answers[i];for(const c of DEST_CHECKS){const z=x.checks?.[c.id];if(z&&typeof z==='object')r.checks[c.id]={status:['pass','fail'].includes(z.status)?z.status:'untested',evidence:typeof z.evidence==='string'?z.evidence.slice(0,3000):''};}for(const f of DEST_FIELDS)if(typeof x.plan?.[f]==='string')r.plan[f]=x.plan[f].slice(0,3000);for(const f of ['spend','cpc','before','after'])if(typeof x.model?.[f]==='string')r.model[f]=x.model[f].slice(0,50);out[b.id]=r;}return out;}
function destinationRecord(){return state.destination[state.business]||(state.destination[state.business]={answers:{},checks:{},plan:{},model:{}});}
function destinationCases(){const shop=state.business==='shop',b2b=state.business==='b2b';const query=shop?'buy running shoes size 42':b2b?'bookkeeping services Karachi':'AC repair Lahore';const promise=shop?'20% off running shoes':b2b?'Book a bookkeeping consultation':'AC repair in Lahore';return[
{title:P('Wada aur page alag','Promise and page disagree'),evidence:P(`Search: ${query}. Ad: ${promise}. Page ${shop?'full-price unrelated sandals dikhata hai; discount ya running shoes nahi':b2b?'sirf accounting jobs dikhata hai; service enquiry nahi':'sirf AC sale dikhata hai; repair booking nahi'}.`,`Search: ${query}. Ad: ${promise}. The page ${shop?'shows unrelated full-price sandals, with no running shoes or discount':b2b?'shows accounting jobs with no service enquiry':'offers AC sales with no repair booking'}.`),options:[P('Sirf bid barhao','Only raise the bid'),P('Relevant destination aur accurate offer/CTA align karo; actual availability test karo','Align a relevant destination and accurate offer/CTA; test actual availability'),P('Har query ko negative kar do','Exclude every query')],answer:1,why:P('Search intent, ad aur page ka connection toot gaya. Pehle matching offer aur next action usable banao; result ko test karo.','The intent/ad/page connection is broken. Make the matching offer and next action usable, then test the result.')},
{title:P('Desktop theek, phone par band','Desktop works, phone fails'),evidence:P('Desktop successful hai. Target region mein phone par final URL 404 return karti hai. Budget change nahi hua.','Desktop succeeds. In the target region the mobile final URL returns HTTP 404. The budget is unchanged.'),options:[P('Destination fault ko foran investigate/fix aur same affected path retest karo','Investigate/fix the destination fault immediately and retest the affected path'),P('Colour test pehle karo','Run a colour test first'),P('404 ko conversion declare karo','Declare the 404 a conversion')],answer:0,why:P('Working desktop mobile availability prove nahi karta. URL, redirect aur server/access logs ki evidence se cause locate karo.','Desktop success does not prove mobile availability. Use URL, redirect and server/access evidence to locate the cause.')},
{title:P('Button click ya business result?','Button click or business result?'),evidence:P(shop?'12 checkout clicks huay, backend mein sirf 3 paid orders hain. Tag click par fire hota hai.':'12 submit clicks huay, backend mein 3 valid enquiries hain. Invalid submit bhi tag fire karta hai.',shop?'There are 12 checkout clicks but only three paid backend orders. The tag fires on a click.':'There are 12 submit clicks but only three valid backend enquiries. Invalid submissions also fire the tag.'),options:[P('12 ko confirmed customers samjho','Treat all 12 as confirmed customers'),P('Sirf form chhota karo, measurement ignore karo','Only shorten the form and ignore measurement'),P('Intended outcome define karo; success trigger, duplicates aur backend reconciliation test karo','Define the intended outcome; test success triggers, duplicates and backend reconciliation')],answer:2,why:P('Click, valid enquiry aur sale alag events hain. Pehle measurement semantics theek karo; phir funnel ka loss diagnose karo.','Clicks, valid enquiries and sales are different events. Correct measurement semantics before diagnosing funnel losses.')},
{title:P('Chhupa hua friction','Hidden friction'),evidence:P(shop?'Size select karte waqt full-screen offer close nahi hoti aur Buy button cover hai.':'Mobile form par dismiss na honay wala overlay submit button cover karta hai.' ,shop?'A full-screen offer cannot be dismissed during size selection and covers Buy.':'A non-dismissible mobile overlay covers the form submit button.'),options:[P('Obstruction remove/fix karo; keyboard/back aur full action path retest karo','Remove/fix the obstruction; retest keyboard/back navigation and the full action path'),P('Zyada traffic bhejo','Send more traffic'),P('Sirf headline pin karo','Only pin the headline')],answer:0,why:P('Visible button ka matlab usable path nahi. Interaction complete kar ke verify karo.','A visible button does not establish a usable journey. Verify by completing the interaction.')},
{title:P('CVR barhi — jeet gaye?','Higher CVR — a winner?'),evidence:P('Before: 100 clicks, 4 valid outcomes. After: 100 clicks, 6 valid outcomes. Traffic mix badla; controlled test aur conversion lag review nahi hua.','Before: 100 clicks, four valid outcomes. After: 100 clicks, six valid outcomes. Traffic mix changed; no controlled test or lag review was completed.'),options:[P('Page ne exactly 50% causal uplift prove ki','The page proved exactly 50% causal uplift'),P('Observed CVR 4% → 6%; uncertainty, quality, lag aur test design review karo','Observed CVR is 4% → 6%; review uncertainty, quality, lag and test design'),P('Har future period mein 6 outcomes guaranteed','Six outcomes are guaranteed in every future period')],answer:1,why:P('Observed improvement aur caused improvement ek claim nahi. Qualified outcomes aur contribution bhi inspect karo.','An observed improvement does not establish causation. Inspect qualified outcomes and contribution too.')},
{title:P('Sab checks pass?','All checks passed?'),evidence:P('Worksheet par sab Pass hain, lekin evidence blank hai aur kisi ne real phone par journey test nahi ki.','Every worksheet item says Pass, but evidence is blank and nobody tested the journey on a real phone.'),options:[P('Google approval guaranteed','Google approval is guaranteed'),P('Quality Score 10/10 guaranteed','Quality Score 10/10 is guaranteed'),P('Untested claims ko verify karo; evidence aur owner record karo','Verify untested claims; record evidence and an owner')],answer:2,why:P('Checklist ek working record hai. Self-reported passes policy approval, live measurement ya results certify nahi kartay.','A checklist is a working record. Self-reported passes do not certify policy approval, live measurement or results.')}
];}
function reviewDestination(r){const failed=[],unknown=[],unsupported=[];for(const c of DEST_CHECKS){const x=r.checks[c.id];if(x?.status==='fail')failed.push(c);else if(x?.status!=='pass')unknown.push(c);else if(!x.evidence.trim())unsupported.push(c);}return{failed,unknown,unsupported,urgent:failed.filter(c=>c.urgent)};}
function destinationMath(v){const n={};for(const f of ['spend','cpc','before','after']){if(!['string','number'].includes(typeof v[f])||String(v[f]).trim()===''||!Number.isFinite(Number(v[f])))return null;n[f]=Number(v[f]);}if(n.spend<0||n.spend>1e9||n.cpc<=0||n.cpc>1e9||[n.before,n.after].some(x=>x<0||x>100))return null;const clicks=n.spend/n.cpc;return{clicks,before:clicks*n.before/100,after:clicks*n.after/100,extra:clicks*(n.after-n.before)/100,costBefore:n.before? n.cpc/(n.before/100):null,costAfter:n.after?n.cpc/(n.after/100):null};}
function destinationSources(){return `<p class="screen-credit">${U('Platform sources checked: 22 Oct 2026. Worksheet mein implementation judgement bhi hai; policy checklist complete nahi.','Platform sources checked: 22 Oct 2026. The worksheet also contains implementation judgement; it is not an exhaustive policy checklist.')}</p><a class="source-link" href="https://support.google.com/google-ads/answer/6238826?hl=en" target="_blank" rel="noopener noreferrer">↗ Google: ads and landing pages</a><a class="source-link" href="https://support.google.com/adspolicy/answer/6368661?hl=en" target="_blank" rel="noopener noreferrer">↗ Google: destination requirements</a>`;}
function destinationPage(){return `${heading('SEARCH ADS · AFTER THE CLICK',U('Click aa gaya. Ab kya?','You got the click. What happens next?'),U('Wada, page aur outcome ko joro. Fault dhoondo, evidence likho, phir test karo.','Connect the promise, page and outcome. Find faults, record evidence, then test.'))}<div class="note">${U('Fictional practice aur manual audit. Koi URL scan, live tag test, Google approval ya Quality Score prediction nahi hoti.','Fictional practice and a manual audit. No URL scanning, live tag testing, Google approval or Quality Score prediction.')}</div><div class="section-heading" style="margin-top:22px"><span class="tag">${esc(t(biz().name))}</span><select class="lang" id="destination-business" aria-label="Landing page business">${BUSINESSES.map(b=>`<option value="${b.id}" ${b.id===state.business?'selected':''}>${esc(t(b.name))}</option>`).join('')}</select></div><div class="tabs"><button data-dest-tab="cases" class="${destinationTab==='cases'?'active':''}">${U('6 fault decisions','6 fault decisions')}</button><button data-dest-tab="audit" class="${destinationTab==='audit'?'active':''}">${U('Apna page audit','Audit your page')}</button><button data-dest-tab="math" class="${destinationTab==='math'?'active':''}">${U('CVR ka hisaab','CVR calculations')}</button></div>${destinationTab==='cases'?destinationCasePage():destinationTab==='audit'?destinationAuditPage():destinationMathPage()}${destinationSources()}${footer()}`;}
function destinationCasePage(){const cases=destinationCases(),c=cases[destinationCase],a=destinationRecord().answers[destinationCase];return `<div class="journey-layout dest-layout"><section class="card"><span class="tag">${destinationCase+1} / 6 · FICTIONAL CASE</span><h2 style="margin-top:18px">${esc(t(c.title))}</h2><div class="note">${esc(t(c.evidence))}</div><h3 style="margin-top:22px">${U('Agla sensible action?','What is the sensible next action?')}</h3><div class="action-row" style="flex-direction:column;align-items:stretch">${c.options.map((o,i)=>`<button class="btn light" data-dest-answer="${i}" aria-pressed="${a===i}">${a===i?'✓ ':''}${esc(t(o))}</button>`).join('')}</div>${a===undefined?'':`<div class="feedback ${a===c.answer?'':'error'}" style="margin-top:20px"><b>${a===c.answer?U('Sahi reasoning.','Sound reasoning.'):U('Evidence dobara dekho.','Review the evidence.')}</b><p>${esc(t(c.why))}</p></div>`}<div class="action-row">${cases.map((_,i)=>`<button class="btn light" data-dest-case="${i}" aria-label="Case ${i+1}" aria-pressed="${i===destinationCase}">${i+1}</button>`).join('')}</div></section><aside class="card"><h3>${U('Fault pehle, polish baad mein','Fix faults before polishing')}</h3><ol class="steps"><li>${U('Page/action broken hai? Cause aur affected users verify karo.','Is the page/action broken? Verify the cause and affected users.')}</li><li>${U('Measurement sach bolti hai? Backend se compare karo.','Is measurement accurate? Compare with the backend.')}</li><li>${U('Offer aur next action clear hain?','Are the offer and next action clear?')}</li><li>${U('Improvement ka test aur guardrail define karo.','Define an improvement test and guardrail.')}</li></ol><button class="btn" data-dest-tab="audit">${U('Apna audit likho','Write your audit')}</button></aside></div>`;}
function destinationAuditPage(){const r=destinationRecord(),labels={query:P('Customer search','Customer search'),promise:P('Ad ka exact wada','Exact ad promise'),url:P('Destination URL · sirf note, scan nahi','Destination URL · note only, no scan'),headline:P('Page ka pehla message','First page message'),cta:P('Primary action aur success condition','Primary action and success condition'),owner:P('Fix ka owner aur due date','Fix owner and due date'),next:P('Agla fix/test aur rollback','Next fix/test and rollback'),evidence:P('Device, date, test steps aur evidence reference','Device, date, test steps and evidence reference')};return `<section class="card"><h2>${U('Search → ad → page → outcome','Search → ad → page → outcome')}</h2><p>${U('Fictional business se practice karo. Real client secrets ya customer data mat likho. Fields aur checks business ke hisaab se autosave hotay hain.','Practice with the fictional business. Avoid client secrets or customer data. Fields/checks autosave separately by business.')}</p><div class="form-grid">${DEST_FIELDS.map(f=>`<label class="field">${esc(t(labels[f]))}<textarea data-dest-plan="${f}" rows="2" maxlength="3000">${esc(r.plan[f]??'')}</textarea></label>`).join('')}</div><h3>${U('8 checks · evidence ke saath','8 checks · with evidence')}</h3>${DEST_CHECKS.map(c=>{const x=r.checks[c.id]||{};return `<article class="dest-check"><h3>${esc(t(c.title))}</h3><p>${esc(t(c.test))}</p><div class="form-grid"><label class="field">Status<select data-dest-status="${c.id}" aria-label="${esc(c.id)} status">${[['untested',P('Abhi test nahi','Not tested')],['fail',P('Fault mila','Fault found')],['pass',P('Test pass','Test passed')]].map(([v,l])=>`<option value="${v}" ${(x.status||'untested')===v?'selected':''}>${esc(t(l))}</option>`).join('')}</select></label><label class="field">${U('Evidence / retest note','Evidence / retest note')}<textarea data-dest-evidence="${c.id}" rows="2" maxlength="3000">${esc(x.evidence||'')}</textarea></label></div></article>`;}).join('')}<small role="status" id="dest-saved">${U('Autosaved in this browser','Autosaved in this browser')}</small><div class="action-row"><button class="btn" id="dest-review">${U('Priority review','Review priorities')}</button><button class="btn light" id="dest-export">${U('Audit download','Download audit')}</button></div><div id="dest-feedback" aria-live="polite"></div></section>`;}
function destinationReviewHTML(){const r=reviewDestination(destinationRecord());return `<div class="feedback ${r.failed.length||r.unknown.length||r.unsupported.length?'error':''}"><h3>${U('Tumhare record ki priorities','Priorities from your record')}</h3><p>${U('Self-reported faults','Self-reported faults')}: ${r.failed.length} · ${U('Untested','Untested')}: ${r.unknown.length} · ${U('Pass lekin evidence blank','Pass with blank evidence')}: ${r.unsupported.length}</p>${r.urgent.length?`<p><b>${U('Pehle investigate/fix','Investigate/fix first')}:</b> ${r.urgent.map(c=>esc(t(c.title))).join(' · ')}</p>`:''}${r.failed.length?`<p>${U('Fault list','Fault list')}: ${r.failed.map(c=>esc(t(c.title))).join(' · ')}</p>`:''}<p>${U('Evidence aur retest ke baghair Pass select karna verification nahi. Saare checks complete bhi hon to Google approval ya live launch certify nahi hota.','Selecting Pass without evidence/retesting is not verification. Even completed checks do not certify Google approval or a live launch.')}</p></div>`;}
function destinationMathPage(){const r=destinationRecord(),v={spend:'10000',cpc:String(biz().cpc),before:'4',after:'6',...r.model};return `<div class="cards"><section class="card"><h2>${U('Same spend. CVR badlay to?','Same spend. What if CVR changes?')}</h2><p>${U('CVR = valid outcomes ÷ clicks × 100. Before/after rates assumptions hain. Dono mein ek hi outcome definition rakho.','CVR = valid outcomes ÷ clicks × 100. Before/after rates are assumptions. Keep the outcome definition identical.')}</p><div class="form-grid">${[['spend','Spend · Rs'],['cpc','CPC · Rs'],['before','Before CVR · %'],['after','After CVR · %']].map(([f,l])=>`<label class="field">${l}<input data-dest-math="${f}" type="number" step="any" value="${esc(v[f])}"></label>`).join('')}</div><div id="dest-math-result" aria-live="polite">${destinationMathHTML(v)}</div></section><aside class="card"><h3>${U('Ye uplift ki proof nahi','This does not prove uplift')}</h3><p>${U('Model spend/CPC fixed rakhta hai. Traffic mix, auction, lag, quality aur capacity ka change include nahi. Fractions expected outcomes hain. Real effect ke liye planned experiment aur mature quality/profit data chahiye.','The model holds spend/CPC fixed. It excludes changes in traffic mix, auction, lag, quality and capacity. Fractions are expected outcomes. A real effect needs a planned experiment and mature quality/profit evidence.')}</p><button class="btn light" data-go="optimize">${U('Experiment planner kholo','Open experiment planner')}</button></aside></div>`;}
function destinationMathHTML(v){const m=destinationMath(v);return m?`<div class="coverage-item"><b>${U('Expected clicks','Expected clicks')}</b><span>${num(m.clicks)}</span></div><div class="coverage-item"><b>${U('Expected outcomes · before → after','Expected outcomes · before → after')}</b><span>${num(m.before)} → ${num(m.after)}</span></div><div class="coverage-item"><b>${U('Outcome difference','Outcome difference')}</b><span>${num(m.extra)}</span></div><div class="coverage-item"><b>${U('Cost / outcome · before → after','Cost / outcome · before → after')}</b><span>${m.costBefore===null?'—':money(m.costBefore)} → ${m.costAfter===null?'—':money(m.costAfter)}</span></div><p>CPC ÷ (CVR / 100) = ${U('cost per outcome. CVR 0 par undefined (—).','cost per outcome. Undefined (—) at zero CVR.')}</p>`:`<div class="feedback error">${U('Valid numbers do: spend ≥ 0, CPC > 0, CVR 0–100. Blank ko zero nahi samjha jata.','Enter valid numbers: spend ≥ 0, CPC > 0, CVR 0–100. Blank is not treated as zero.')}</div>`;}
function bindDestination(){const r=destinationRecord();$('#destination-business').onchange=e=>{state.business=e.target.value;save();render();};$$('[data-dest-tab]').forEach(b=>b.onclick=()=>{destinationTab=b.dataset.destTab;render();});$$('[data-dest-case]').forEach(b=>b.onclick=()=>{destinationCase=+b.dataset.destCase;render();});$$('[data-dest-answer]').forEach(b=>b.onclick=()=>{r.answers[destinationCase]=+b.dataset.destAnswer;save();const y=window.scrollY;render();window.scrollTo(0,y);});const touch=()=>{save();const f=$('#dest-feedback');if(f)f.innerHTML='';};$$('[data-dest-plan]').forEach(x=>x.oninput=()=>{r.plan[x.dataset.destPlan]=x.value;touch();});$$('[data-dest-status]').forEach(x=>x.onchange=()=>{const k=x.dataset.destStatus;r.checks[k]={status:x.value,evidence:r.checks[k]?.evidence||''};touch();});$$('[data-dest-evidence]').forEach(x=>x.oninput=()=>{const k=x.dataset.destEvidence;r.checks[k]={status:r.checks[k]?.status||'untested',evidence:x.value};touch();});if($('#dest-review'))$('#dest-review').onclick=()=>$('#dest-feedback').innerHTML=destinationReviewHTML();if($('#dest-export'))$('#dest-export').onclick=()=>download('ads-asaan-'+state.business+'-landing-audit.json',{simulation:true,manualSelfReport:true,business:biz().name[1],audit:r,review:reviewDestination(r),notice:'No URL scan, policy certification, live measurement verification or predicted results.'});$$('[data-dest-math]').forEach(x=>x.oninput=()=>{r.model[x.dataset.destMath]=x.value;save();const v=Object.fromEntries($$('[data-dest-math]').map(e=>[e.dataset.destMath,e.value]));$('#dest-math-result').innerHTML=destinationMathHTML(v);});}
